package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
	"sync"

	"github.com/go-git/go-git/v6"
)

// commonDirCache memoizes resolved git common dirs by worktree root. The value
// cannot change for a worktree's lifetime, and resolving it costs a git
// subprocess (~10ms) — which the push-discovery queue pays on EVERY checkpoint
// ref write and the ephemeral store pays on every shadow-branch write, i.e.
// once per agent turn on the hook path and once per turn imported by `entire
// import`. Mirrors session.getGitCommonDir, which already caches this same
// value process-wide for its own callers.
//
// Only successes are cached: a failure may be transient (a canceled context
// fails the subprocess instantly), and caching it would poison every later
// caller in the process.
var (
	commonDirMu    sync.RWMutex
	commonDirCache = map[string]string{} // worktree root -> resolved common dir
)

// cachedCommonDir returns the memoized common dir for a worktree root.
func cachedCommonDir(root string) (string, bool) {
	commonDirMu.RLock()
	defer commonDirMu.RUnlock()
	dir, ok := commonDirCache[root]
	return dir, ok
}

func resolveGitCommonDir(ctx context.Context, repo *git.Repository) (string, error) {
	worktree, err := repo.Worktree()
	if err != nil {
		return "", fmt.Errorf("open worktree for git common dir: %w", err)
	}
	root := worktree.Filesystem().Root()
	if root == "" {
		return "", errors.New("resolve worktree root for git common dir")
	}
	if cached, ok := cachedCommonDir(root); ok {
		return cached, nil
	}

	cmd := exec.CommandContext(ctx, "git", "-C", root, "rev-parse", "--git-common-dir")
	// Use Output (not CombinedOutput) so stderr never pollutes the resolved
	// path on success. Output populates ExitError.Stderr when cmd.Stderr is
	// nil, so error detail is still available without merging streams.
	output, err := cmd.Output()
	if err != nil {
		var exitErr *exec.ExitError
		if errors.As(err, &exitErr) {
			if detail := strings.TrimSpace(string(exitErr.Stderr)); detail != "" {
				return "", fmt.Errorf("resolve git common dir: %w: %s", err, detail)
			}
		}
		return "", fmt.Errorf("resolve git common dir: %w", err)
	}
	commonDir := strings.TrimSpace(string(output))
	if commonDir == "" {
		return "", errors.New("resolve git common dir: empty output")
	}
	if !filepath.IsAbs(commonDir) {
		commonDir = filepath.Join(root, commonDir)
	}
	commonDir = filepath.Clean(commonDir)
	commonDirMu.Lock()
	commonDirCache[root] = commonDir
	commonDirMu.Unlock()
	return commonDir, nil
}
package checkpoint

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/gitdir"
	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

// Push-discovery queue file names, kept in the git common dir so every worktree
// sharing the object store enqueues into one queue. The git-refs backend cannot
// push every local checkpoint ref at pre-push time (reads fetch refs too, and
// deleting them after push would hurt local workflows), so each write records
// the ref it touched here and pre-push drains + batch-pushes exactly those.
const (
	pushQueueFileName = "entire-checkpoint-push-queue.jsonl"
	pushQueueLockName = "entire-checkpoint-push-queue.lock"
)

// lock opens the common dir's root and takes the queue lock inside it,
// returning the root so the caller's reads and writes use the same handle.
func (q *PushQueue) lock() (*os.Root, func(), error) {
	root, err := q.root()
	if err != nil {
		return nil, nil, fmt.Errorf("open git common dir: %w", err)
	}
	release, err := flock.AcquireIn(root, pushQueueLockName)
	if err != nil {
		return nil, nil, fmt.Errorf("lock push queue: %w", err)
	}
	return root, release, nil
}

// pushQueueEntry is one JSONL record: a checkpoint ref awaiting push.
type pushQueueEntry struct {
	Ref string `json:"ref"`
}

// PushQueue is a flock-protected JSONL list of checkpoint refs awaiting push,
// stored in the git common dir. Entries are removed only after a confirmed push
// (Remove), so an interrupted or failed push leaves them for the next pre-push.
// Duplicates are tolerated on disk and collapsed by Drain.
type PushQueue struct {
	dir string
}

// root returns the shared *os.Root over the git common dir the queue lives in.
// Every read, write, lock and rename below is a name inside it.
func (q *PushQueue) root() (*os.Root, error) {
	return gitdir.OpenAt(q.dir) //nolint:wrapcheck // gitdir names the directory; the caller adds the queue context
}

// NewPushQueue returns the push queue rooted at gitCommonDir.
func NewPushQueue(gitCommonDir string) *PushQueue {
	return &PushQueue{dir: gitCommonDir}
}

// PushQueueForRepo resolves the git common dir for repo and returns its queue.
func PushQueueForRepo(ctx context.Context, repo *git.Repository) (*PushQueue, error) {
	dir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return nil, err
	}
	return NewPushQueue(dir), nil
}

func (q *PushQueue) queuePath() string { return filepath.Join(q.dir, pushQueueFileName) }

// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
// present (or already pushed): Drain collapses duplicates and the batch push is
// idempotent. Enqueue takes the lock so concurrent writers never interleave a
// partial line.
func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
	root, release, err := q.lock()
	if err != nil {
		return err
	}
	defer release()

	line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
	if err != nil {
		return fmt.Errorf("encode push queue entry: %w", err)
	}
	f, err := root.OpenFile(pushQueueFileName, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
	if err != nil {
		return fmt.Errorf("open push queue: %w", err)
	}
	defer f.Close()
	if _, err := f.Write(append(line, '\n')); err != nil {
		return fmt.Errorf("append push queue entry: %w", err)
	}
	return nil
}

// Drain returns the de-duplicated refs currently queued, in first-seen order. It
// does NOT remove them; call Remove after a confirmed push so a failed push
// retries next time. A missing queue file yields no refs.
//
// It compacts the file in place: when the on-disk queue held redundant lines
// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
// it to the de-duplicated set. Enqueue only ever appends, so without this the
// file would grow unboundedly between the Removes that are otherwise the sole
// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
// checkpoint ref but never pushes).
func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
	root, release, err := q.lock()
	if err != nil {
		return nil, err
	}
	defer release()

	refs, rawLines, err := q.readLocked(root)
	if err != nil {
		return nil, err
	}
	if rawLines > len(refs) {
		if err := q.rewriteLocked(root, refs); err != nil {
			return nil, err
		}
	}
	return refs, nil
}

// Peek returns the de-duplicated refs currently queued, in first-seen order,
// without mutating the queue file. Read-only counterpart to Drain (which
// compacts redundant lines in place) — for counters/status displays that must
// observe the queue without owning a push. A missing queue file yields no refs.
func (q *PushQueue) Peek() ([]plumbing.ReferenceName, error) {
	root, release, err := q.lock()
	if err != nil {
		return nil, err
	}
	defer release()

	refs, _, err := q.readLocked(root)
	return refs, err
}

// Remove deletes the given refs from the queue, preserving any entries appended
// after a Drain (e.g. a write that landed during the push). Called after a
// confirmed push.
func (q *PushQueue) Remove(refs []plumbing.ReferenceName) error {
	if len(refs) == 0 {
		return nil
	}
	root, release, err := q.lock()
	if err != nil {
		return err
	}
	defer release()

	current, _, err := q.readLocked(root)
	if err != nil {
		return err
	}
	removed := make(map[string]struct{}, len(refs))
	for _, r := range refs {
		removed[r.String()] = struct{}{}
	}
	kept := make([]plumbing.ReferenceName, 0, len(current))
	for _, r := range current {
		if _, drop := removed[r.String()]; drop {
			continue
		}
		kept = append(kept, r)
	}
	return q.rewriteLocked(root, kept)
}

// rewriteLocked replaces the queue file with exactly refs (de-duplicated, one
// line each), or removes the file when refs is empty so a clean repo has no
// stray queue. The caller must hold the lock. The write is atomic (temp file +
// rename) so a concurrent reader never sees a half-written queue.
func (q *PushQueue) rewriteLocked(root *os.Root, refs []plumbing.ReferenceName) error {
	if len(refs) == 0 {
		if err := root.Remove(pushQueueFileName); err != nil && !os.IsNotExist(err) {
			return fmt.Errorf("remove empty push queue: %w", err)
		}
		return nil
	}
	var buf bytes.Buffer
	for _, r := range refs {
		line, err := json.Marshal(pushQueueEntry{Ref: r.String()})
		if err != nil {
			return fmt.Errorf("encode push queue entry: %w", err)
		}
		buf.Write(line)
		buf.WriteByte('\n')
	}
	if err := writeQueueAtomic(root, buf.Bytes()); err != nil {
		return fmt.Errorf("rewrite push queue: %w", err)
	}
	return nil
}

// readLocked parses the queue file into de-duplicated refs, preserving first-seen
// order. The caller must hold the lock. Malformed lines are skipped rather than
// failing the whole drain — a single bad record must not strand every queued ref.
//
// rawLines is the number of non-empty lines seen (including duplicates and
// malformed records), so callers can detect when the file holds more than the
// de-duplicated set and is worth compacting: rawLines > len(refs) exactly when
// there were redundant lines.
func (q *PushQueue) readLocked(root *os.Root) (refs []plumbing.ReferenceName, rawLines int, err error) {
	f, err := root.Open(pushQueueFileName)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, 0, nil
		}
		return nil, 0, fmt.Errorf("open push queue: %w", err)
	}
	defer f.Close()

	seen := make(map[string]struct{})
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for scanner.Scan() {
		line := bytes.TrimSpace(scanner.Bytes())
		if len(line) == 0 {
			continue
		}
		rawLines++
		var entry pushQueueEntry
		if err := json.Unmarshal(line, &entry); err != nil || entry.Ref == "" {
			continue
		}
		if _, dup := seen[entry.Ref]; dup {
			continue
		}
		seen[entry.Ref] = struct{}{}
package checkpoint

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/gitdir"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/redact"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

// Transcripts are append-only JSONL, but every checkpoint used to re-redact them
// from byte zero: a 70MB Codex rollout cost ~67s per Stop hook, and a session
// with N checkpoints re-redacted O(N^2) bytes overall. Redaction is ~99.7% of
// that write path (git object writing is milliseconds), and it is by far the
// dominant cost of a Stop hook on a large session.
//
// So keep the redacted output for the prefix already processed and redact only
// what was appended. Correctness rests on two properties:
//
//   - Redaction is per-line and stateless (see redact.redactJSONLLines), so
//     redacting a prefix and a suffix separately and concatenating them yields
//     exactly what redacting the whole file would. redact's own tests pin this
//     as redact(A+B) == redact(A)+redact(B) for newline-terminated A.
//   - A cached prefix always ends immediately after a "\n". Because of that the
//     redacted prefix also ends with "\n", and plain byte concatenation
//     reproduces the full result with no boundary fixups.
//
// The prefix is only reused when the source bytes it covered still hash the
// same and the redaction rules have not changed. Anything else -- a rewritten
// transcript, a compaction, changed custom rules, a CLI upgrade -- falls back to
// redacting everything.
//
// Scope: all three whole-transcript paths reuse prefixes -- the shadow-branch
// metadata write (via createRedactedBlobFromFile, which walks files), and
// post-commit condensation and the Stop finalize rewrite (via
// RedactTranscriptCached, which hold the transcript in memory).
// Single-JSON-value transcripts (OpenCode export) get only the sharding in
// redact.JSONLContent, since they have no line structure to split on.
//
// Those paths do NOT all redact the same bytes: the metadata walk stores a
// sanitized transcript, while condensation and finalize store a sanitized *and*
// image-externalized one. They stay separate because their cache keys are
// different strings -- the walk uses its real tree path, the in-memory callers a
// synthetic one (see transcriptCacheKey) -- and a key is hashed into its own
// file. Sharing a key would be safe, since the prefix hash check rejects a
// mismatch, but it would miss on every checkpoint.

const (
	// RedactCacheDirName sits in the git common dir, NOT under .entire/, because
	// anything inside the worktree metadata directory would be walked into the
	// checkpoint tree and committed.
	//
	// Exported so `entire clean` can reclaim it: every entry is derived data that
	// is rebuilt on the next checkpoint, so the whole directory is safe to delete
	// at any time.
	RedactCacheDirName = "entire-redact-cache"
)

// redactCacheMinBytes is the file size below which incremental reuse is not
// worth its bookkeeping; a small file redacts in milliseconds.
//
// A var rather than a const so tests can lower it: every test of this cache
// otherwise has to build and redact a megabyte of realistic content, and
// redaction is the expensive part -- the suite cost minutes under -race and
// timed out CI. Production never assigns to it.
var redactCacheMinBytes = 1 << 20 // 1MiB

// redactPrefixEntry is the persisted record of one file's already-redacted
// prefix. Written atomically; a missing, unreadable, or stale entry simply means
// a full redaction.
type redactPrefixEntry struct {
	// Fingerprint identifies the redaction rules that produced RedactedBlob.
	Fingerprint string `json:"fingerprint"`
	// SourceBytes is the length of the source prefix covered, always ending
	// immediately after a newline.
	SourceBytes int `json:"source_bytes"`
	// SourceHash is the SHA-256 of source[:SourceBytes], proving the prefix has
	// not been rewritten underneath us.
	SourceHash string `json:"source_hash"`
	// RedactedBlob is the git blob holding the redacted prefix. Set by the
	// metadata walk, which had to write that blob for the checkpoint tree anyway.
	RedactedBlob string `json:"redacted_blob,omitempty"`
	// RedactedFile names a file beside this entry holding the redacted prefix.
	// Used by callers that hold a transcript in memory, for whom a git blob is
	// pure overhead: go-git deflates the whole payload before discovering the
	// object already exists (dotgit dedups the rename, not the compression), so a
	// 65MB transcript cost ~1-2s of zlib per checkpoint. Worse, the store chunks
	// transcripts at agent.MaxChunkSize (50MB), so above that the whole-transcript
	// blob matches no chunk, is never deduped, and leaves an unreachable object
	// per checkpoint that `git gc` later prunes -- silently reverting the cache to
	// full redaction. A plain file has none of that, and `entire clean` already
	// reclaims this directory.
	RedactedFile string `json:"redacted_file,omitempty"`
}

// redactCache reads and writes redactPrefixEntry records under a directory in
// the git common dir. A nil *redactCache disables incremental reuse, which is
// what every caller that cannot resolve the git dir gets.
type redactCache struct {
	// dir is the absolute cache directory, kept for messages. All I/O is a name
	// inside root, the shared *os.Root over the git common dir: entry names are
	// hashes of tree paths, which are safe by construction, but going through
	// the root means that stays true without anyone re-deriving the argument.
	dir  string
	root *os.Root
	name string
}

// newRedactCache returns a cache rooted at gitCommonDir, or nil when the
// directory is empty or cannot be created. Callers treat nil as "no caching".
func newRedactCache(gitCommonDir string) *redactCache {
	if gitCommonDir == "" {
		return nil
	}
	root, err := gitdir.OpenAt(gitCommonDir)
	if err != nil {
		return nil
	}
	if err := osroot.MkdirAllNoSymlink(root, RedactCacheDirName, 0o700); err != nil {
		return nil
	}
	return &redactCache{
		dir:  filepath.Join(gitCommonDir, RedactCacheDirName),
		root: root,
		name: RedactCacheDirName,
	}
}

// repoRedactCache resolves the prefix cache for repo, or nil when the git common
// directory is unavailable (a bare repository, for instance). Nil disables
// incremental reuse without failing the write.
//
// resolveGitCommonDir memoizes per worktree and the sibling shadow-branch and
// push-queue writes already warm it, so this is cheap to call per checkpoint.
func repoRedactCache(ctx context.Context, repo *git.Repository) *redactCache {
	dir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return nil
	}
	return newRedactCache(dir)
}

// redactionFingerprint combines the redaction config with the CLI build. The
// build is a deliberately conservative proxy for the vendored betterleaks
// ruleset and the pipeline itself, neither of which is introspectable: an
// upgrade invalidates every cached prefix and costs one full redaction.
func redactionFingerprint() string {
	return versioninfo.Version + ":" + versioninfo.Commit + ":" + redact.ConfigFingerprint()
}

// entryName renders a tree path's cache entry as a name relative to c.root.
func (c *redactCache) entryName(treePath string) string {
	sum := sha256.Sum256([]byte(treePath))
	return c.name + "/" + hex.EncodeToString(sum[:]) + ".json"
}

func (c *redactCache) load(treePath string) *redactPrefixEntry {
	data, err := osroot.ReadFileNoFollow(c.root, c.entryName(treePath))
	if err != nil {
		return nil
	}
	var entry redactPrefixEntry
	if err := json.Unmarshal(data, &entry); err != nil {
		return nil
	}
	if entry.SourceBytes <= 0 || entry.SourceHash == "" {
		return nil
	}
	if entry.RedactedBlob == "" && entry.RedactedFile == "" {
		return nil
	}
	return &entry
}

// storePrefix records the prefix just written so the next checkpoint can reuse
// it. sourceHash must be the digest of the whole of the source content, and blob
// the object holding its redacted form.
//
// Failures are silent: losing a cache entry only costs a full redaction next
// time.
func (c *redactCache) storePrefix(ctx context.Context, treePath, sourceHash string, sourceBytes int, blob plumbing.Hash) {
	c.writeEntry(ctx, treePath, redactPrefixEntry{
		Fingerprint:  redactionFingerprint(),
		SourceBytes:  sourceBytes,
		SourceHash:   sourceHash,
		RedactedBlob: blob.String(),
	})
}

// storePrefixBytes is storePrefix for callers with no blob to point at: it writes
// the redacted prefix as a file beside the entry. See redactPrefixEntry.
func (c *redactCache) storePrefixBytes(ctx context.Context, treePath, sourceHash string, sourceBytes int, redacted []byte) {
	if c == nil {
		return
	}
	name := prefixFileName(treePath)
	if err := jsonutil.WriteFileAtomicIn(c.root, c.name+"/"+name, redacted, 0o600); err != nil {
		logging.Debug(logging.WithComponent(ctx, "redaction"),
			"failed to store redaction prefix bytes", slog.String("error", err.Error()))
		return
	}
	c.writeEntry(ctx, treePath, redactPrefixEntry{
		Fingerprint:  redactionFingerprint(),
		SourceBytes:  sourceBytes,
		SourceHash:   sourceHash,
		RedactedFile: name,
	})
}

// writeEntry persists the record itself. Written after any prefix payload, so a
// crash between the two leaves an entry-less payload (ignored, reclaimed by
// `entire clean`) rather than an entry pointing at nothing.
func (c *redactCache) writeEntry(ctx context.Context, treePath string, entry redactPrefixEntry) {
	if c == nil {
		return
	}
	data, err := json.Marshal(entry)
	if err != nil {
		return
	}
	if err := jsonutil.WriteFileAtomicIn(c.root, c.entryName(treePath), data, 0o600); err != nil {
		logging.Debug(logging.WithComponent(ctx, "redaction"),
			"failed to store redaction prefix cache", slog.String("error", err.Error()))
	}

