		_ = storage.Close()
		return nil, err
	}
	if usesReftable {
		repo, err := git.Open(newReftableStorer(storage, metadata.GitDir), worktreeFS)
		if err != nil {
			_ = storage.Close()
			return nil, fmt.Errorf("open reftable repository storage: %w", err)
