	dir  string
	root *os.Root
	name string
}

// newRedactCache returns a cache rooted at gitCommonDir, or nil when the
// directory is empty or cannot be created. Callers treat nil as "no caching".
func newRedactCache(gitCommonDir string) *redactCache {
	if gitCommonDir == "" {
		return nil
	}
	root, err := gitdir.OpenAt(gitCommonDir)
	if err != nil {
		return nil
	}
	if err := osroot.MkdirAllNoSymlink(root, RedactCacheDirName, 0o700); err != nil {
		return nil
	}
	return &redactCache{
		dir:  filepath.Join(gitCommonDir, RedactCacheDirName),
		root: root,
		name: RedactCacheDirName,
	}
}

// repoRedactCache resolves the prefix cache for repo, or nil when the git common
// directory is unavailable (a bare repository, for instance). Nil disables
// incremental reuse without failing the write.
//
// resolveGitCommonDir memoizes per worktree and the sibling shadow-branch and
// push-queue writes already warm it, so this is cheap to call per checkpoint.
func repoRedactCache(ctx context.Context, repo *git.Repository) *redactCache {
	dir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return nil
	}
	return newRedactCache(dir)
}

// redactionFingerprint combines the redaction config with the CLI build. The
// build is a deliberately conservative proxy for the vendored betterleaks
// ruleset and the pipeline itself, neither of which is introspectable: an
// upgrade invalidates every cached prefix and costs one full redaction.
func redactionFingerprint() string {
	return versioninfo.Version + ":" + versioninfo.Commit + ":" + redact.ConfigFingerprint()
}

// entryName renders a tree path's cache entry as a name relative to c.root.
func (c *redactCache) entryName(treePath string) string {
	sum := sha256.Sum256([]byte(treePath))
	return c.name + "/" + hex.EncodeToString(sum[:]) + ".json"
}

func (c *redactCache) load(treePath string) *redactPrefixEntry {
	data, err := osroot.ReadFileNoFollow(c.root, c.entryName(treePath))
	if err != nil {
		return nil
	}
	var entry redactPrefixEntry
	if err := json.Unmarshal(data, &entry); err != nil {
		return nil
	if err != nil {
		return plumbing.ZeroHash, nil, err
	}
	return s.refTip(cid, ref)
}

// refTip reads the commit and tree at a resolved checkpoint ref.
func (s *gitRefsStore) refTip(cid id.CheckpointID, ref *plumbing.Reference) (plumbing.Hash, *object.Tree, error) {
	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
	}
	return ref.Hash(), tree, nil
}

// enqueueForPush records refName in the push-discovery queue, logging (never
// returning) on failure so the local ref write still succeeds.
//
// The queue is resolved with the cancellation stripped from ctx. By the time we
// get here the ref is already written locally, and the queue is the ONLY
// push-discovery mechanism there is — see the
// pushQueueFileName doc. A ref that misses the queue is never pushed, and the
// writers above are idempotent, so a re-run skips it as already-present and
// never re-enqueues it: it stays local-only forever. Resolving the queue shells
// out to `git rev-parse --git-common-dir`, which fails instantly on a canceled
// ctx, so honoring cancellation here would drop the bookkeeping for a write
// that already happened. This local, sub-millisecond step therefore completes
// even during shutdown (a second Ctrl-C still force-quits the process).
func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
	q, err := PushQueueForRepo(context.WithoutCancel(ctx), s.repo)
	if err != nil {
		logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
		return
	}
	if err := q.Enqueue(refName); err != nil {
		logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
	}
}

func (s *gitRefsStore) updateCheckpointRef(
	ctx context.Context,
	cid id.CheckpointID,
	base func() (plumbing.Hash, *object.Tree, error),
	build func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error),
) error {
	refName, err := RefName(cid)
	if err != nil {
		return err
	}
	err = updatePersistentRef(ctx, s.repo, refName, func() (plumbing.Hash, plumbing.Hash, error) {
		parentHash, existing, baseErr := base()
		if baseErr != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, baseErr
		}
		newHash, buildErr := build(parentHash, existing)
		return newHash, parentHash, buildErr
	})
	if err != nil {
		return err
	}
	s.enqueueForPush(ctx, refName)
	return nil
}

func (s *gitRefsStore) writeSession(ctx context.Context, opts WriteOptions) error {
