package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/logging"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
)

type persistentRefBuilder func() (newHash, expectedHash plumbing.Hash, err error)

func repositoryDirs(ctx context.Context, repo *git.Repository) (worktreeRoot, commonDir string, err error) {
	wt, err := repo.Worktree()
	if err != nil {
		return "", "", fmt.Errorf("open worktree: %w", err)
	}
	worktreeRoot = wt.Filesystem().Root()
	if worktreeRoot == "" {
		return "", "", errors.New("repository worktree filesystem has no root path")
	}
	commonDir, err = resolveGitCommonDir(ctx, repo)
	if err != nil {
		return "", "", err
	}
	return worktreeRoot, commonDir, nil
}

// casUpdateRef atomically updates refName through native Git's lock protocol.
// Pass ZeroHash as expectedHash to require that the ref does not exist.
func casUpdateRef(ctx context.Context, repoRoot string, refName plumbing.ReferenceName, newHash, expectedHash plumbing.Hash) error {
	newValue := newHash.String()
	oldValue := strings.Repeat("0", newHash.HexSize())
	if expectedHash != plumbing.ZeroHash {
		oldValue = expectedHash.String()
	}

	cmd := exec.CommandContext(ctx, "git", "update-ref", refName.String(), newValue, oldValue)
	cmd.Dir = repoRoot
	cmd.Env = append(os.Environ(), "LC_ALL=C", "LANG=C")
	output, err := cmd.CombinedOutput()
	if err == nil {
		return nil
	}

	out := string(output)
	if strings.Contains(out, "cannot lock ref") || strings.Contains(out, "but expected") {
		return ErrShadowRefBusy
	}
	return fmt.Errorf("git update-ref %s: %s: %w", refName, strings.TrimSpace(out), err)
}

func persistentRefLockPath(commonDir string, refName plumbing.ReferenceName) (string, error) {
	lockDir := filepath.Join(commonDir, "entire-persistent-ref-locks")
	if err := os.MkdirAll(lockDir, 0o750); err != nil {
		return "", fmt.Errorf("create persistent ref lock directory: %w", err)
	}
	safe := strings.NewReplacer("/", "_", "\\", "_", ":", "_").Replace(refName.String())
	return filepath.Join(lockDir, safe+".lock"), nil
}

func withPersistentRefFlock(ctx context.Context, commonDir string, refName plumbing.ReferenceName, fn func() error) error {
	path, err := persistentRefLockPath(commonDir, refName)
	if err != nil {
		return err
	}
	release, err := flock.AcquireContext(ctx, path)
	if err != nil {
		return fmt.Errorf("acquire persistent ref flock %s: %w", refName, err)
	}
	defer release()
	return fn()
}

// updatePersistentRef serializes Entire writers for one ref and retains a CAS
// retry for native Git or other external writers. build runs again after every
// conflict, so each retry reconstructs its tree and commit from the fresh tip.
func updatePersistentRef(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, build persistentRefBuilder) error {
	repoRoot, commonDir, err := repositoryDirs(ctx, repo)
	if err != nil {
		return fmt.Errorf("resolve repository directories: %w", err)
	}

	return withPersistentRefFlock(ctx, commonDir, refName, func() error {
		for attempt := range shadowRefMaxRetries {
			newHash, expectedHash, buildErr := build()
			if buildErr != nil {
				return buildErr
			}

			refErr := casUpdateRef(ctx, repoRoot, refName, newHash, expectedHash)
			if refErr == nil {
				return nil
			}
			if !errors.Is(refErr, ErrShadowRefBusy) {
				return fmt.Errorf("update persistent ref %s: %w", refName, refErr)
			}
			if newHash != expectedHash {
				tryDeleteLooseObject(commonDir, newHash)
			}

			if backoffErr := shadowRefBackoff(ctx, attempt); backoffErr != nil {
				return backoffErr
			}
		}

		logging.Warn(logging.WithComponent(ctx, "checkpoint"),
			"persistent ref CAS retry budget exhausted",
			slog.String("ref", refName.String()),
			slog.Int("retries", shadowRefMaxRetries),
		)
		return fmt.Errorf("failed to update persistent ref %s after %d CAS retries: %w", refName, shadowRefMaxRetries, ErrShadowRefBusy)
	})
}
package checkpoint

import (
	"context"
	"errors"
	"fmt"
	"math/rand/v2"
	"os"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/gitdir"
	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/osroot"

	"github.com/go-git/go-git/v6/plumbing"
)

// ErrShadowRefBusy is returned by casUpdateShadowBranchRef when the ref has
// moved since the caller read it. Callers retry with a fresh parent.
var ErrShadowRefBusy = errors.New("shadow branch ref moved (CAS mismatch)")

// shadowRefMaxRetries bounds the WriteTemporary retry loop. With the
// per-shadow-branch flock held, our own writers never collide; this budget
// is purely a safety net against an external `git update-ref` writer that
// repeatedly beats us to the ref.
const shadowRefMaxRetries = 16

// shadowRefMaxJitter is the upper bound for randomized backoff between CAS
// retries. Random jitter avoids thundering-herd retry patterns when many
// sessions hit the same shadow branch simultaneously.
const shadowRefMaxJitter = 8 * time.Millisecond

// repoDirs returns the worktree root and git common dir for the store's
// repository. Callers use the worktree root as cmd.Dir for git invocations
// and the common dir to locate filesystem paths (lock files, loose objects)
// — both without depending on the process cwd.
func (s *ephemeralStore) repoDirs(ctx context.Context) (worktreeRoot, commonDir string, err error) {
	return repositoryDirs(ctx, s.repo)
}

// casUpdateShadowBranchRef atomically updates a shadow branch ref via
// `git update-ref <ref> <new> <old>`. Pass plumbing.ZeroHash as expectedHash
// to require the ref to NOT exist (first-checkpoint case).
//
// repoRoot is used as cmd.Dir so the update targets the same repository as
// the rest of WriteTemporary (i.e. s.repo) regardless of the process cwd.
//
// Returns ErrShadowRefBusy when git reports the ref moved since expectedHash
// was observed; callers retry with a fresh parent. Any other failure is
// returned wrapped.
//
// Why shell out: git's ref-locking is the canonical cross-process atomic
// CAS — go-git's CheckAndSetReference doesn't interoperate with native git's
// .lock files, and shadow branches can be touched concurrently by separate
// `entire` hook processes.
func casUpdateShadowBranchRef(ctx context.Context, repoRoot, branchName string, newHash, expectedHash plumbing.Hash) error {
	return casUpdateRef(ctx, repoRoot, plumbing.NewBranchReferenceName(branchName), newHash, expectedHash)
}

// shadowRefBackoff sleeps for a small random jitter before the next CAS
// retry. After several retries the upper bound doubles to slow the
// thundering herd further. Respects context cancellation.
func shadowRefBackoff(ctx context.Context, attempt int) error {
	base := shadowRefMaxJitter
	if attempt > 4 {
		base *= 2
	}
	// Add a 1ms floor so the chosen sleep is always non-trivial, even when
	// rand.Int64N happens to return 0.
	d := time.Duration(rand.Int64N(int64(base))) + time.Millisecond //nolint:gosec // jitter, not security-sensitive
	select {
	case <-time.After(d):
		return nil
	case <-ctx.Done():
		return ctx.Err() //nolint:wrapcheck // canonical context cancellation
	}
}

// shadowBranchLockPath returns the per-shadow-branch flock file path. Lock
// files live in <git-common-dir>/entire-shadow-locks/ so they don't pollute
// the session-state directory. Branch names are slash-escaped because the
// shadow-branch convention "entire/<hash>" would otherwise nest directories.
func shadowBranchLock(commonDir, branchName string) (*os.Root, string, error) {
	root, err := gitdir.OpenAt(commonDir)
	if err != nil {
		return nil, "", fmt.Errorf("open git common dir: %w", err)
	}
	if err := osroot.MkdirAllNoSymlink(root, shadowLockDirName, 0o750); err != nil {
		return nil, "", fmt.Errorf("create shadow lock directory: %w", err)
	}
	safe := strings.ReplaceAll(branchName, "/", "_")
	return root, shadowLockDirName + "/" + safe + ".lock", nil
}

// shadowLockDirName is the shadow-branch lock directory inside the git common dir.
const shadowLockDirName = "entire-shadow-locks"

// withShadowBranchFlock acquires the per-shadow-branch flock, runs fn, and
// releases the flock. Serializes all WriteTemporary callers that target the
// same shadow branch — across goroutines AND across processes — so the CAS
// in casUpdateShadowBranchRef only sees external writers as contention.
//
// commonDir is the git common directory (from s.repoDirs); it locates the
// lock file independently of the process cwd.
func withShadowBranchFlock(commonDir, branchName string, fn func() error) error {
	root, name, err := shadowBranchLock(commonDir, branchName)
	if err != nil {
		return err
	}
	release, err := flock.AcquireIn(root, name)
	if err != nil {
		return fmt.Errorf("acquire shadow flock %s: %w", branchName, err)
	}
	defer release()
	return fn()
}

// tryDeleteLooseObject best-effort removes a loose object file. Used to
// clean up dangling commits created during a CAS-losing attempt. Failures
// (e.g. object already packed by a concurrent gc, or never written as a
// loose object) are ignored — the object will be picked up by the next gc
// pass either way.
func tryDeleteLooseObject(commonDir string, hash plumbing.Hash) {
	h := hash.String()
	if len(h) < 3 {
		return
	}
	// Through the common dir's root like everything else in this file: a delete
	// is the operation least worth leaving on a joined path, and the shadow
	// flock beside it already resolves its name inside this same root. The hash
	// is hex, so nothing here can traverse today; the root is what keeps that
	// true without depending on it.
	root, err := gitdir.OpenAt(commonDir)
	if err != nil {
		return
	}
	_ = osroot.RemoveNoSymlinks(root, "objects/"+h[:2]+"/"+h[2:]) //nolint:errcheck // best-effort; see doc comment
}
package checkpoint

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/gitdir"
	"github.com/entireio/cli/cmd/entire/cli/internal/flock"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
)

// Push-discovery queue file names, kept in the git common dir so every worktree
// sharing the object store enqueues into one queue. The git-refs backend cannot
// push every local checkpoint ref at pre-push time (reads fetch refs too, and
// deleting them after push would hurt local workflows), so each write records
// the ref it touched here and pre-push drains + batch-pushes exactly those.
const (
	pushQueueFileName = "entire-checkpoint-push-queue.jsonl"
	pushQueueLockName = "entire-checkpoint-push-queue.lock"
)

// lock opens the common dir's root and takes the queue lock inside it,
// returning the root so the caller's reads and writes use the same handle.
func (q *PushQueue) lock() (*os.Root, func(), error) {
	root, err := q.root()
	if err != nil {
		return nil, nil, fmt.Errorf("open git common dir: %w", err)
	}
	release, err := flock.AcquireIn(root, pushQueueLockName)
	if err != nil {
		return nil, nil, fmt.Errorf("lock push queue: %w", err)
	}
	return root, release, nil
}

// pushQueueEntry is one JSONL record: a checkpoint ref awaiting push.
type pushQueueEntry struct {
	Ref string `json:"ref"`
}

// PushQueue is a flock-protected JSONL list of checkpoint refs awaiting push,
// stored in the git common dir. Entries are removed only after a confirmed push
// (Remove), so an interrupted or failed push leaves them for the next pre-push.
// Duplicates are tolerated on disk and collapsed by Drain.
type PushQueue struct {
	dir string
}

// root returns the shared *os.Root over the git common dir the queue lives in.
// Every read, write, lock and rename below is a name inside it.
func (q *PushQueue) root() (*os.Root, error) {
	return gitdir.OpenAt(q.dir) //nolint:wrapcheck // gitdir names the directory; the caller adds the queue context
}

// NewPushQueue returns the push queue rooted at gitCommonDir.
func NewPushQueue(gitCommonDir string) *PushQueue {
	return &PushQueue{dir: gitCommonDir}
}

// PushQueueForRepo resolves the git common dir for repo and returns its queue.
func PushQueueForRepo(ctx context.Context, repo *git.Repository) (*PushQueue, error) {
	dir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return nil, err
	}
	return NewPushQueue(dir), nil
}

func (q *PushQueue) queuePath() string { return filepath.Join(q.dir, pushQueueFileName) }

// Enqueue appends a ref to the queue. It is safe to enqueue a ref already
// present (or already pushed): Drain collapses duplicates and the batch push is
// idempotent. Enqueue takes the lock so concurrent writers never interleave a
// partial line.
func (q *PushQueue) Enqueue(ref plumbing.ReferenceName) error {
	root, release, err := q.lock()
	if err != nil {
		return err
	}
	defer release()

	line, err := json.Marshal(pushQueueEntry{Ref: ref.String()})
	if err != nil {
		return fmt.Errorf("encode push queue entry: %w", err)
	}
	f, err := root.OpenFile(pushQueueFileName, os.O_CREATE|os.O_WRONLY|os.O_APPEND, 0o600)
	if err != nil {
		return fmt.Errorf("open push queue: %w", err)
	}
	defer f.Close()
	if _, err := f.Write(append(line, '\n')); err != nil {
		return fmt.Errorf("append push queue entry: %w", err)
	}
	return nil
}

// Drain returns the de-duplicated refs currently queued, in first-seen order. It
// does NOT remove them; call Remove after a confirmed push so a failed push
// retries next time. A missing queue file yields no refs.
//
// It compacts the file in place: when the on-disk queue held redundant lines
// (duplicate enqueues of the same ref, or malformed/blank lines), Drain rewrites
// it to the de-duplicated set. Enqueue only ever appends, so without this the
// file would grow unboundedly between the Removes that are otherwise the sole
// compaction point (e.g. a long-lived session that keeps re-enqueuing the same
// checkpoint ref but never pushes).
func (q *PushQueue) Drain() ([]plumbing.ReferenceName, error) {
	root, release, err := q.lock()
	if err != nil {
		return nil, err
	}
	defer release()

	refs, rawLines, err := q.readLocked(root)
	if err != nil {
		return nil, err
	}
	if rawLines > len(refs) {
		if err := q.rewriteLocked(root, refs); err != nil {
			return nil, err
		}
	}
type redactCache struct {
	// dir is the absolute cache directory, kept for messages. All I/O is a name
	// inside root, the shared *os.Root over the git common dir: entry names are
	// hashes of tree paths, which are safe by construction, but going through
	// the root means that stays true without anyone re-deriving the argument.
	dir  string
	root *os.Root
	name string
}

// newRedactCache returns a cache rooted at gitCommonDir, or nil when the
// directory is empty or cannot be created. Callers treat nil as "no caching".
func newRedactCache(gitCommonDir string) *redactCache {
	if gitCommonDir == "" {
		return nil
	}
	root, err := gitdir.OpenAt(gitCommonDir)
	if err != nil {
		return nil
	}
	if err := osroot.MkdirAllNoSymlink(root, RedactCacheDirName, 0o700); err != nil {
		return nil
	}
	return &redactCache{
		dir:  filepath.Join(gitCommonDir, RedactCacheDirName),
		root: root,
		name: RedactCacheDirName,
	}
}

// repoRedactCache resolves the prefix cache for repo, or nil when the git common
// directory is unavailable (a bare repository, for instance). Nil disables
// incremental reuse without failing the write.
//
// resolveGitCommonDir memoizes per worktree and the sibling shadow-branch and
// push-queue writes already warm it, so this is cheap to call per checkpoint.
func repoRedactCache(ctx context.Context, repo *git.Repository) *redactCache {
	dir, err := resolveGitCommonDir(ctx, repo)
	if err != nil {
		return nil
	}
	return newRedactCache(dir)
}

// redactionFingerprint combines the redaction config with the CLI build. The
// build is a deliberately conservative proxy for the vendored betterleaks
// ruleset and the pipeline itself, neither of which is introspectable: an
// upgrade invalidates every cached prefix and costs one full redaction.
func redactionFingerprint() string {
	return versioninfo.Version + ":" + versioninfo.Commit + ":" + redact.ConfigFingerprint()
}

// entryName renders a tree path's cache entry as a name relative to c.root.
func (c *redactCache) entryName(treePath string) string {
	sum := sha256.Sum256([]byte(treePath))
	return c.name + "/" + hex.EncodeToString(sum[:]) + ".json"
}

func (c *redactCache) load(treePath string) *redactPrefixEntry {
	data, err := osroot.ReadFileNoFollow(c.root, c.entryName(treePath))
	if err != nil {
		return nil
	}
	var entry redactPrefixEntry
	if err := json.Unmarshal(data, &entry); err != nil {
		return nil
	if err != nil {
		return plumbing.ZeroHash, nil, err
	}
	return s.refTip(cid, ref)
}

// refTip reads the commit and tree at a resolved checkpoint ref.
func (s *gitRefsStore) refTip(cid id.CheckpointID, ref *plumbing.Reference) (plumbing.Hash, *object.Tree, error) {
	commit, err := s.repo.CommitObject(ref.Hash())
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint commit %s: %w", ref.Hash(), err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return plumbing.ZeroHash, nil, fmt.Errorf("read checkpoint tree for %s: %w", cid, err)
	}
	return ref.Hash(), tree, nil
}

// enqueueForPush records refName in the push-discovery queue, logging (never
// returning) on failure so the local ref write still succeeds.
//
// The queue is resolved with the cancellation stripped from ctx. By the time we
// get here the ref is already written locally, and the queue is the ONLY
// push-discovery mechanism there is — see the
// pushQueueFileName doc. A ref that misses the queue is never pushed, and the
// writers above are idempotent, so a re-run skips it as already-present and
// never re-enqueues it: it stays local-only forever. Resolving the queue shells
// out to `git rev-parse --git-common-dir`, which fails instantly on a canceled
// ctx, so honoring cancellation here would drop the bookkeeping for a write
// that already happened. This local, sub-millisecond step therefore completes
// even during shutdown (a second Ctrl-C still force-quits the process).
func (s *gitRefsStore) enqueueForPush(ctx context.Context, refName plumbing.ReferenceName) {
	q, err := PushQueueForRepo(context.WithoutCancel(ctx), s.repo)
	if err != nil {
		logging.Warn(ctx, "checkpoint: resolve push queue failed; ref not enqueued",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
		return
	}
	if err := q.Enqueue(refName); err != nil {
		logging.Warn(ctx, "checkpoint: enqueue checkpoint ref for push failed",
			slog.String("ref", refName.String()), slog.String("error", err.Error()))
	}
}

func (s *gitRefsStore) updateCheckpointRef(
	ctx context.Context,
	cid id.CheckpointID,
	base func() (plumbing.Hash, *object.Tree, error),
	build func(parentHash plumbing.Hash, existing *object.Tree) (plumbing.Hash, error),
) error {
	refName, err := RefName(cid)
	if err != nil {
		return err
	}
	err = updatePersistentRef(ctx, s.repo, refName, func() (plumbing.Hash, plumbing.Hash, error) {
		parentHash, existing, baseErr := base()
		if baseErr != nil {
			return plumbing.ZeroHash, plumbing.ZeroHash, baseErr
		}
		newHash, buildErr := build(parentHash, existing)
		return newHash, parentHash, buildErr
	})
	if err != nil {
		return err
	}
	s.enqueueForPush(ctx, refName)
	return nil
}

